pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a + b);
        try c.deposit{value: a}() {} catch { return; }
        try c.deposit{value: b}() {} catch { return; }
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint totalDeposit = a + b;
        uint midThis = address(this).balance;
        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint finalThis = address(this).balance;
        assertTrue((totalDeposit == 0 && beforeC == afterC && beforeThis == afterThis)
            ||
            // Case totalDeposit > 0:
            (totalDeposit > 0 && (
                // either first withdraw reverted: balances unchanged
                (reverted && beforeC == afterC && beforeThis == afterThis)
                ||
                // or first withdraw succeeded: this contract gained exactly totalDeposit and subsequent withdraw transfer is zero
                (!reverted && afterThis == beforeThis + totalDeposit && afterC + totalDeposit == beforeC && finalThis == afterThis)
            )));
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}
}
